arguments.command:
kubectl exec -n hotel-reservation deploy/consul -- sh -c 'echo "== hotelIds =="; curl -s -m 15 -w "
HTTP %{http_code}
" "http://frontend:5000/recommendations?hotelIds=1&hotelIds=2&lat=37.7749&lon=-122.4194"; echo "== inDate/outDate =="; curl -s -m 15 -w "
HTTP %{http_code}
" "http://frontend:5000/recommendations?inDate=2015-04-09&outDate=2015-04-10&lat=37.7749&lon=-122.4194"'

kubectl exec -n hotel-reservation deploy/consul -- sh -c 'echo "== A =="; curl -s -m 15 -w " HTTP %{http_code}
" "http://frontend:5000/recommendations?hotelId=1&require=1&lat=37.7749&lon=-122.4194"; echo "== B =="; curl -s -m 15 -w " HTTP %{http_code}
" "http://frontend:5000/recommendations?hotelIds=1,2&require=1&lat=37.7749&lon=-122.4194"; echo "== C =="; curl -s -m 15 -w " HTTP %{http_code}
" "http://frontend:5000/recommendations?lat=37.7749&lon=-122.4194&require=1&inDate=2015-04-09&outDate=2015-04-10"'

kubectl exec -n hotel-reservation deploy/consul -- sh -c 'echo "=== RECOMMEND (dis) ==="; curl -s -m 20 -w "
HTTP %{http_code}
" "http://frontend:5000/recommendations?lat=37.7749&lon=-122.4194&require=rate" | head -8; echo "=== RECOMMEND (price) ==="; curl -s -m 20 -w "
HTTP %{http_code}
" "http://frontend:5000/recommendations?lat=37.7749&lon=-122.4194&require=price" | head -8'
